    internal int Syntax_Range()
    {
        // <SnippetIndicesAndRanges_Range>
        string[] secondThirdFourth = words[1..4]; // contains "second", "third" and "fourth"

        // < second >< third >< fourth >
        foreach (var word in secondThirdFourth)
            Console.Write($"< {word} >"); 
        Console.WriteLine();
        // </SnippetIndicesAndRanges_Range>
